laisse épaissir 3 min.","timer":{"label":"Sauce","min":3}}],"kids":true},{"title":"Porc au caramel express","intro":"Le porc au caramel pour un soir de semaine.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"quick caramel pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat vietnamien","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":1,"unit":"","have":false},{"name":"sucre roux","plural":"sucre roux","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"nuoc-mâm","plural":"nuoc-mâm","qty":1,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false}],"steps":[{"text":"Coupe le filet mignon en fines tranches.","timer":null},{"text":"Fais-les saisir dans l'huile 4 min.","timer":{"label":"Poêle","min":4}},{"text":"Ajoute le sucre, l'ail, la sauce soja et le nuoc-mâm, et laisse caraméliser 5 min.","timer":{"label":"Poêle","min":5}}]},{"title":"Rôti de porc au miel et aux épices","intro":"Un rôti laqué, sucré-salé et parfumé.","minutes":80,"calories":560,"difficulty":"Facile","imageSearch":"honey glazed pork roast","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rôti de porc","plural":"rôtis de porc","qty":1000,"unit":"g","have":false},{"name":"miel","plural":"miel","qty":3,"unit":"c. à s.","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"quatre-épices","plural":"quatre-épices","qty":1,"unit":"c. à c.","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":800,"unit":"g","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 190 °C.","timer":null},{"text":"Mélange le miel, la sauce soja, l'ail haché et les épices.","timer":null},{"text":"Mets le rôti dans un plat avec les pommes de terre en morceaux et badigeonne-le de sauce.","timer":null},{"text":"Enfourne 1 h en arrosant toutes les 20 min.","timer":{"label":"Four","min":60}}]},{"title":"Porc aigre-doux","intro":"Le classique des restaurants chinois, au porc.","minutes":30,"calories":580,"difficulty":"Facile","imageSearch":"sweet and sour pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"filet mignon de porc","plural":"filets mignons de porc","qty":1,"unit":"","have":false},{"name":"fécule de maïs","plural":"fécule de maïs","qty":3,"unit":"c. à s.","have":false},{"name":"ananas","plural":"ananas","qty":200,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":3,"unit":"c. à s.","have":false},{"name":"vinaigre de riz","plural":"vinaigre de riz","qty":2,"unit":"c. à s.","have":false},{"name":"sucre","plural":"sucre","qty":2,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false}],"steps":[{"text":"Prépare la sauce : ketchup, vinaigre, sucre et 10 cl d'eau.","timer":null},{"text":"Coupe le porc en dés, enrobe-le de fécule et fais-le dorer 6 min.","timer":{"label":"Poêle","min":6}},{"text":"Fais sauter le poivron, l'oignon et l'ananas 4 min.","timer":{"label":"Wok","min":4}},{"text":"Ajoute la sauce et le porc, et laisse épaissir 2 min.","timer":{"label":"Wok","min":2}}]}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('jambon', 'jambon', array[]::text[], 'list', $r$[{"title":"Endives au jambon","intro":"Des endives fondantes roulées dans du jambon, gratinées sous une béchamel.","minutes":60,"calories":480,"difficulty":"Facile","imageSearch":"endives ham gratin bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Nord","serves":4,"items":[{"name":"endive","plural":"endives","qty":8,"unit":"","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":8,"unit":"tranches","have":false},{"name":"beurre","plural":"beurres","qty":40,"unit":"g","have":false},{"name":"farine","plural":"farines","qty":40,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":50,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les endives 20 min à la vapeur ou dans l'eau, puis presse-les bien pour les égoutter.","timer":{"label":"Cuisson","min":20}},{"text":"Fais une béchamel : beurre fondu, farine, puis lait en fouettant 5 min. Ajoute muscade, sel et poivre.","timer":{"label":"Béchamel","min":5}},{"text":"Préchauffe le four à 200 °C. Roule chaque endive dans une tranche de jambon et range-les dans un plat.","timer":null},{"text":"Nappe de béchamel et parsème d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true},{"title":"Croque-monsieur","intro":"Le croque doré et fondant, avec du jambon, de l'emmental et une touche de béchamel.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"croque monsieur ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pain de mie","plural":"pains de mie","qty":8,"unit":"tranches","have":false},{"name":"jambon blanc","plural":"jambon blanc","qty":4,"unit":"tranches","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":120,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":30,"unit":"g","have":false},{"name":"lait","plural":"laits","qty":15,"unit":"cl","have":false},{"name":"farine","plural":"farines","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais une petite béchamel : fais fondre 15 g de beurre, ajoute la farine, puis le lait en fouettant 3 min.","timer":{"label":"Béchamel","min":3}},{"text":"Préchauffe le four à 220 °C. Beurre légèrement les tranches de pain à l'extérieur.","timer":null},{"text":"Garnis 4 tranches de béchamel, de jambon et d'emmental, puis couvre avec les autres tranches.","timer":null},{"text":"Ajoute un peu de béchamel et d'emmental sur le dessus.","timer":null},{"text":"Enfourne 10 min, jusqu'à ce que ce soit bien doré.","timer":{"label":"Four","min":10}}],"kids":true},{"title":"Riz cantonais","intro":"Le riz sauté du traiteur : jambon, œufs, petits pois et sauce soja.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"cantonese fried rice","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat chinois","serves":4,"items":[{"name":"riz cuit","plural":"riz cuit","qty":600,"unit":"g","have":false},{"name":"dés de jambon","plural":"dés de jambon","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Bats les œufs et fais-les cuire en omelette fine dans 1 c. à s. d'huile, puis coupe-la en lanières.","timer":{"label":"Poêle","min":2}},{"text":"Fais sauter le riz froid dans le reste d'huile 5 min à feu vif.","timer":{"label":"Wok","min":5}},{"text":"Ajoute le jambon, les petits pois et les oignons 3 min.","timer":{"label":"Wok","min":3}},{"text":"Ajoute la sauce soja et l'omelette, et mélange.","timer":null}],"kids":true},{"title":"Quiche lorraine légère","intro":"Tout le goût de la quiche, avec un appareil plus léger.","minutes":50,"calories":420,"difficulty":"Facile","imageSearch":"light ham quiche","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"dés de jambon","plural":"dés de jambon","qty":150,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"lait demi-écrémé","plural":"laits demi-écrémé","qty":40,"unit":"cl","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule et pique le fond.","timer":null},{"text":"Répartis les dés de jambon sur la pâte.","timer":null},{"text":"Bats les œufs avec le lait, la muscade, sel et poivre.","timer":null},{"text":"Verse et enfourne 35 min.","timer":{"label":"Four","min":35}}]},{"title":"Tartiflette légère","intro":"Toute la gourmandise de la tartiflette, en plus léger pour la semaine.","minutes":55,"calories":520,"difficulty":"Facile","imageSearch":"light tartiflette potato","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité savoyarde","serves":4,"items":[{"name":"pomme de terre","plural":"pommes de terre","qty":1000,"unit":"g","have":false},{"name":"reblochon","plu