,{"title":"Paella au poulet","intro":"La paella des familles, au poulet et au chorizo.","minutes":50,"calories":620,"difficulty":"Moyen","imageSearch":"chicken chorizo paella","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat espagnol","serves":4,"items":[{"name":"riz rond","plural":"riz rond","qty":350,"unit":"g","have":false},{"name":"haut de cuisse de poulet","plural":"hauts de cuisse de poulet","qty":6,"unit":"","have":false},{"name":"chorizo","plural":"chorizo","qty":100,"unit":"g","have":false},{"name":"petits pois","plural":"petits pois","qty":150,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"tomate","plural":"tomates","qty":2,"unit":"","have":false},{"name":"safran","plural":"safran","qty":1,"unit":"","have":false},{"name":"bouillon de volaille","plural":"bouillons de volaille","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais dorer le poulet et le chorizo dans l'huile.","timer":null},{"text":"Ajoute l'oignon, le poivron et les tomates, cuis 5 min.","timer":{"label":"Cuisson","min":5}},{"text":"Ajoute le riz, le safran et 1 l de bouillon chaud.","timer":null},{"text":"Cuis 20 min sans remuer, ajoute les petits pois les 5 dernières minutes.","timer":{"label":"Cuisson","min":20}}],"kids":true},{"title":"One pot pasta chorizo","intro":"La version relevée du one pot, au chorizo et aux poivrons.","minutes":15,"calories":600,"difficulty":"Facile","imageSearch":"one pot pasta chorizo","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"chorizo","plural":"chorizo","qty":120,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":1,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Mets les pâtes, le chorizo en rondelles, les tomates, le poivron et l'oignon émincés dans une casserole.","timer":null},{"text":"Verse 80 cl d'eau et sale légèrement.","timer":null},{"text":"Cuis 12 min à frémissement en remuant souvent.","timer":{"label":"Cuisson","min":12}}],"kids":true}]$r$::jsonb, 'claude')
