insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('saucisse', 'saucisse', array[]::text[], 'list', $r$[{"title":"Choucroute garnie","intro":"Le chou fermenté mijoté au vin blanc, avec saucisses, lard et pommes de terre.","minutes":120,"calories":780,"difficulty":"Facile","imageSearch":"choucroute sauerkraut sausages","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spécialité alsacienne","serves":4,"items":[{"name":"choucroute crue","plural":"choucroute crue","qty":1200,"unit":"g","have":false},{"name":"saucisse de Strasbourg","plural":"saucisses de Strasbourg","qty":4,"unit":"","have":false},{"name":"saucisse de Montbéliard","plural":"saucisses de Montbéliard","qty":2,"unit":"","have":false},{"name":"lard fumé","plural":"lard fumé","qty":300,"unit":"g","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":8,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":25,"unit":"cl","have":false},{"name":"baie de genièvre","plural":"baies de genièvre","qty":6,"unit":"","have":false},{"name":"saindoux","plural":"saindoux","qty":1,"unit":"c. à s.","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Rince la choucroute et égoutte-la bien.","timer":null},{"text":"Fais revenir l'oignon dans le saindoux, ajoute la choucroute, le genièvre, le vin et 25 cl d'eau.","timer":null},{"text":"Ajoute le lard et laisse mijoter 1 h à couvert.","timer":{"label":"Mijotage","min":60}},{"text":"Ajoute les saucisses de Montbéliard et les pommes de terre épluchées, cuis 30 min.","timer":{"label":"Cuisson","min":30}},{"text":"Ajoute les saucisses de Strasbourg 10 min avant la fin.","timer":{"label":"Cuisson","min":10}}]},{"title":"Cassoulet","intro":"Haricots blancs fondants, saucisse de Toulouse et confit de canard, gratinés au four.","minutes":180,"calories":850,"difficulty":"Moyen","imageSearch":"cassoulet beans sausage duck","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Sud-Ouest","serves":4,"items":[{"name":"haricot blanc sec","plural":"haricots blancs secs","qty":500,"unit":"g","have":false},{"name":"saucisse de Toulouse","plural":"saucisses de Toulouse","qty":4,"unit":"","have":false},{"name":"cuisse de canard confite","plural":"cuisses de canard confites","qty":2,"unit":"","have":false},{"name":"poitrine fumée","plural":"poitrine fumée","qty":150,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":2,"unit":"","have":false},{"name":"carotte","plural":"carottes","qty":2,"unit":"","have":false},{"name":"ail","plural":"ails","qty":4,"unit":"gousse","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"chapelure","plural":"chapelure","qty":3,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"La veille, fais tremper les haricots dans l'eau froide.","timer":null},{"text":"Fais cuire les haricots 1 h dans l'eau avec la carotte, l'oignon et le bouquet garni.","timer":{"label":"Cuisson","min":60}},{"text":"Fais dorer la poitrine en dés, les saucisses et le canard dans une poêle.","timer":null},{"text":"Préchauffe le four à 160 °C. Dans un plat, mélange les haricots égouttés, les tomates, l'ail et les viandes, et ajoute un peu d'eau de cuisson.","timer":null},{"text":"Saupoudre de chapelure et enfourne 1 h 30, en cassant la croûte deux fois.","timer":{"label":"Four","min":90}}]},{"title":"Choucroute express","intro":"La choucroute pour un soir de semaine.","minutes":35,"calories":700,"difficulty":"Facile","imageSearch":"quick sauerkraut sausage","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"choucroute cuite","plural":"choucroute cuite","qty":1000,"unit":"g","have":false},{"name":"saucisse de Strasbourg","plural":"saucisses de Strasbourg","qty":4,"unit":"","have":false},{"name":"saucisse fumée","plural":"saucisses fumées","qty":2,"unit":"","have":false},{"name":"pomme de terre","plural":"pommes de terre","qty":6,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":15,"unit":"cl","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais cuire les pommes de terre 20 min dans l'eau salée.","timer":{"label":"Cuisson","min":20}},{"text":"Fais chauffer la choucroute avec le vin blanc et les saucisses fumées 20 min à couvert.","timer":{"label":"Cuisson","min":20}},{"text":"Ajoute les saucisses de Strasbourg 8 min avant la fin et sers avec les pommes de terre.","timer":{"label":"Cuisson","min":8}}]},{"title":"Cassoulet express","intro":"Le goût du cassoulet sans y passer la journée.","minutes":45,"calories":780,"difficulty":"Facile","imageSearch":"quick cassoulet beans","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité du Sud-Ouest","serves":4,"items":[{"name":"haricot blanc","plural":"haricots blancs","qty":800,"unit":"g","have":false},{"name":"saucisse de Toulouse","plural":"saucisses de Toulouse","qty":4,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":100,"unit":"g","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":400,"unit":"g","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"chapelure","plural":"chapelure","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C.","timer":null},{"text":"Fais dorer les saucisses coupées en tronçons, les lardons et l'oignon 10 min.","timer":{"label":"Poêle","min":10}},{"text":"Ajoute les haricots égouttés, les tomates et l'ail, sale et poivre.","timer":null},{"text":"Verse dans un plat, saupoudre de chapelure et enfourne 25 min.","timer":{"label":"Four","min":25}}]}]$r$::jsonb, 'claude')
