insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('oeuf', 'oeuf', array[]::text[], 'list', $r$[{"title":"Shakshuka","intro":"Des œufs pochés dans une sauce tomate aux poivrons, au cumin et au paprika.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"shakshuka eggs tomato","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat du Maghreb","serves":4,"items":[{"name":"œuf","plural":"œufs","qty":6,"unit":"","have":false},{"name":"tomate concassée","plural":"tomates concassées","qty":800,"unit":"g","have":false},{"name":"poivron rouge","plural":"poivrons rouges","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"ail","plural":"ails","qty":2,"unit":"gousse","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"c. à c.","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"c. à c.","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false}],"steps":[{"text":"Fais revenir l'oignon et les poivrons en lanières dans l'huile 8 min.","timer":{"label":"Poêle","min":8}},{"text":"Ajoute l'ail, les épices et les tomates, sale et laisse mijoter 10 min.","timer":{"label":"Mijotage","min":10}},{"text":"Creuse des petits trous et casse un œuf dans chacun.","timer":null},{"text":"Couvre et laisse cuire 6 min, jusqu'à ce que les blancs soient pris.","timer":{"label":"Cuisson","min":6}},{"text":"Parsème de coriandre et sers avec du pain.","timer":null}]},{"title":"Gâteau au chocolat","intro":"Le gâteau au chocolat fondant au cœur, le dessert préféré de tous.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"chocolate cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chocolat noir","plural":"chocolat noir","qty":200,"unit":"g","have":false},{"name":"beurre","plural":"beurres","qty":150,"unit":"g","have":false},{"name":"sucre","plural":"sucre","qty":120,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"farine","plural":"farines","qty":60,"unit":"g","have":false}],"steps":[{"text":"Préchauffe le four à 180 °C.","timer":null},{"text":"Fais fondre le chocolat et le beurre ensemble.","timer":null},{"text":"Fouette les œufs avec le sucre, puis ajoute le chocolat et la farine.","timer":null},{"text":"Verse dans un moule beurré et enfourne 22 min : le centre doit rester tremblotant.","timer":{"label":"Four","min":22}}],"kids":true,"dessert":true},{"title":"Gratin de courgettes","intro":"Des courgettes fondantes dans un appareil crémeux, gratinées à l'emmental.","minutes":40,"calories":320,"difficulty":"Facile","imageSearch":"zucchini gratin cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"emmental râpé","plural":"emmental râpé","qty":80,"unit":"g","have":false},{"name":"ail","plural":"ails","qty":1,"unit":"gousse","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":1,"unit":"c. à s.","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Coupe les courgettes en rondelles.","timer":null},{"text":"Fais-les revenir 8 min à la poêle avec l'huile et l'ail.","timer":{"label":"Poêle","min":8}},{"text":"Bats les œufs avec la crème, la moitié de l'emmental, sel et poivre.","timer":null},{"text":"Mets les courgettes dans un plat, verse l'appareil et parsème du reste d'emmental.","timer":null},{"text":"Enfourne 25 min.","timer":{"label":"Four","min":25}}],"kids":true},{"title":"Pad thaï au poulet","intro":"Les nouilles de riz sautées à la thaïe : poulet, œuf, cacahuètes et citron vert.","minutes":30,"calories":560,"difficulty":"Moyen","imageSearch":"chicken pad thai","veg":false,"oven":false,"cold":false,"missing":"","origin":"Plat thaïlandais","serves":4,"items":[{"name":"nouilles de riz","plural":"nouilles de riz","qty":250,"unit":"g","have":false},{"name":"blanc de poulet","plural":"blancs de poulet","qty":2,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":2,"unit":"","have":false},{"name":"pousse de soja","plural":"pousses de soja","qty":150,"unit":"g","have":false},{"name":"cacahuète","plural":"cacahuètes","qty":40,"unit":"g","have":false},{"name":"citron vert","plural":"citrons verts","qty":2,"unit":"","have":false},{"name":"sauce soja","plural":"sauce soja","qty":3,"unit":"c. à s.","have":false},{"name":"sucre roux","plural":"sucre roux","qty":1,"unit":"c. à s.","have":false},{"name":"oignon nouveau","plural":"oignons nouveaux","qty":2,"unit":"","have":false},{"name":"huile d'olive","plural":"huile d'olive","qty":2,"unit":"c. à s.","have":false}],"steps":[{"text":"Fais tremper les nouilles 10 min dans l'eau chaude, puis égoutte-les.","timer":{"label":"Trempage","min":10}},{"text":"Fais sauter le poulet en lanières 5 min dans l'huile.","timer":{"label":"Wok","min":5}},{"text":"Pousse-le sur le côté et brouille les œufs.","timer":null},{"text":"Ajoute les nouilles, la sauce soja, le sucre et le jus d'un citron vert, et fais sauter 3 min.","timer":{"label":"Wok","min":3}},{"text":"Ajoute les pousses de soja et les oignons, et sers avec les cacahuètes concassées et le citron vert.","timer":null}]},{"title":"Quiche lorraine","intro":"La vraie quiche lorraine : une pâte croustillante, des lardons et un appareil crémeux aux œufs.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"quiche lorraine","veg":false,"oven":true,"cold":false,"missing":"","origin":"Spécialité lorraine","serves":4,"items":[{"name":"pâte brisée","plural":"pâtes brisées","qty":1,"unit":"","have":false},{"name":"lardon","plural":"lardons","qty":200,"unit":"g","have":false},{"name":"œuf","plural":"œufs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crèmes fraîche","qty":20,"unit":"cl","have":false},{"name":"lait","plural":"laits","qty":20,"unit":"cl","have":false},{"name":"noix de muscade","plural":"noix de muscade","qty":null,"unit":"","have":false},{"name":"sel","plural":"sels","qty":null,"unit":"","have":false},{"name":"poivre","plural":"poivres","qty":null,"unit":"","have":false}],"steps":[{"text":"Préchauffe le four à 200 °C. Étale la pâte dans un moule et pique le fond.","timer":null},{"text":"Fais revenir les lardons 5 min à la poêle, sans matière grasse, et répartis-les sur la pâte.","timer":{"label":"Poêle","min":5}},{"text":"Bats les œufs avec la crème, le lait, un peu de sel, du poivre et la muscade.","timer":null},{"text":"Verse sur les lardons et enfourne 35 min, jusqu'à ce que ce soit doré.","timer":{"label":"Four","min":35}}],"kids":true},{"title":"Salade niçoise","intro":"La salade du Sud : thon, œufs durs, tomates, olives et anchois, avec une vinaigrette à l'huile d'olive.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"nicoise salad tuna egg","veg":false,"oven":false,"cold":true,"missing":"","origin":"Spécialité niçoise","serves":4,"items":[{"name":"tomate","plural":"tomates","qty":4,"unit":"","have":false},{"name":"œuf","plural":"œufs","qty":4,"unit":"","have":false},{"name":"thon au naturel","plural":"thon au naturel","qty":200,"unit":"g","have":false},{"name":"poivron vert","plural":"poivrons verts","qty":1,"unit":"","have":false},{"name":"oignon rouge","plural":"oignons rouges","qty":1,"unit":"","have":false},{"name":"olive noire","plural":"olives noires","qty":60,"unit":"g","have":false},{"name":"anchois","plural":"anchois","qty":8,"unit":"","have":false},{"name":"huile d'olive","plural"